function serializeOptions(options) {
  if (
    options === null ||
    typeof options !== "object" ||
    (Object.getPrototypeOf(options) !== Object.prototype &&
      Object.getPrototypeOf(options) !== null)
  ) {
    throw new TypeError("Expected an ordinary object");
  }

  function encode(value) {
    var result = "";

    for (var i = 0; i < value.length; i++) {
      var code = value.charCodeAt(i);

      if (code >= 0xd800 && code <= 0xdbff) {
        if (i + 1 >= value.length) throw new URIError("Unpaired surrogate");
        var low = value.charCodeAt(++i);
        if (low < 0xdc00 || low > 0xdfff) {
          throw new URIError("Unpaired surrogate");
        }
        code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
      } else if (code >= 0xdc00 && code <= 0xdfff) {
        throw new URIError("Unpaired surrogate");
      }

      if (
        (code >= 0x41 && code <= 0x5a) ||
        (code >= 0x61 && code <= 0x7a) ||
        (code >= 0x30 && code <= 0x39) ||
        code === 0x2d ||
        code === 0x2e ||
        code === 0x5f ||
        code === 0x7e
      ) {
        result += String.fromCharCode(code);
      } else {
        var bytes;

        if (code <= 0x7f) {
          bytes = [code];
        } else if (code <= 0x7ff) {
          bytes = [
            0xc0 | (code >> 6),
            0x80 | (code & 0x3f)
          ];
        } else if (code <= 0xffff) {
          bytes = [
            0xe0 | (code >> 12),
            0x80 | ((code >> 6) & 0x3f),
            0x80 | (code & 0x3f)
          ];
        } else {
          bytes = [
            0xf0 | (code >> 18),
            0x80 | ((code >> 12) & 0x3f),
            0x80 | ((code >> 6) & 0x3f),
            0x80 | (code & 0x3f)
          ];
        }

        for (var j = 0; j < bytes.length; j++) {
          result += "%" + bytes[j].toString(16).toUpperCase().padStart(2, "0");
        }
      }
    }

    return result;
  }

  var pairs = [];
  var keys = Object.keys(options);

  for (var i = 0; i < keys.length; i++) {
    var key = keys[i];
    var value = options[key];

    if (value === undefined) continue;

    if (
      typeof value !== "string" &&
      typeof value !== "number" &&
      typeof value !== "boolean" &&
      value !== null
    ) {
      throw new TypeError("Unsupported value type");
    }

    if (typeof value === "number" && !Number.isFinite(value)) {
      throw new TypeError("Number must be finite");
    }

    var stringValue = value === null ? "" : String(value);
    var encodedName = encode(key);
    var encodedValue = encode(stringValue);

    pairs.push({
      name: encodedName,
      value: encodedValue
    });
  }

  pairs.sort(function (a, b) {
    return a.name < b.name
      ? -1
      : a.name > b.name
        ? 1
        : a.value < b.value
          ? -1
          : a.value > b.value
            ? 1
            : 0;
  });

  return pairs
    .map(function (pair) {
      return pair.name + "=" + pair.value;
    })
    .join("&");
}
